#include "netpulse/net.hpp"
#include "netpulse/protocol.hpp"
#include "netpulse/statistics.hpp"
#include <arpa/inet.h>
#include <netinet/in.h>
#include <sys/socket.h>
#include <sys/poll.h>
#include <unistd.h>
#include <signal.h>
#include <atomic>
#include <cerrno>
#include <chrono>
#include <cstring>
#include <iostream>
#include <mutex>
#include <thread>
#include <vector>
#include <algorithm>
namespace netpulse {
static std::atomic<bool> stopping{false};
static void on_signal(int){stopping=true;}
struct Fd{int n=-1;explicit Fd(int x=-1):n(x){}~Fd(){if(n>=0)::close(n);}Fd(const Fd&)=delete;Fd&operator=(const Fd&)=delete;Fd(Fd&&o)noexcept:n(o.n){o.n=-1;}int release(){int x=n;n=-1;return x;}};
static bool readn(int fd,void*buf,std::size_t n){auto*p=static_cast<char*>(buf);std::size_t off=0;while(off<n){pollfd ready{fd,POLLIN,0};int pr=::poll(&ready,1,100);if(pr==0){if(stopping)return false;continue;}if(pr<0){if(errno==EINTR)continue;return false;}ssize_t r=::recv(fd,p+off,n-off,0);if(r==0)return false;if(r<0){if(errno==EINTR||errno==EAGAIN||errno==EWOULDBLOCK)continue;return false;}off+=static_cast<std::size_t>(r);}return true;}
static bool writen(int fd,const void*buf,std::size_t n){auto*p=static_cast<const char*>(buf);std::size_t off=0;while(off<n){ssize_t r=::send(fd,p+off,n-off,MSG_NOSIGNAL);if(r<0){if(errno==EINTR)continue;return false;}if(r==0)return false;off+=static_cast<std::size_t>(r);}return true;}
static bool tcp_recv(int fd,Message&m){std::uint8_t h[kHeaderSize];if(!readn(fd,h,sizeof(h)))return false;std::uint32_t len=(std::uint32_t(h[12])<<24)|(std::uint32_t(h[13])<<16)|(std::uint32_t(h[14])<<8)|h[15];if(len>kMaxPayload)return false;std::vector<std::uint8_t>b(kHeaderSize+len);std::memcpy(b.data(),h,kHeaderSize);if(len&&!readn(fd,b.data()+kHeaderSize,len))return false;std::string e;return decode(b.data(),b.size(),m,e);}
static bool tcp_send(int fd,const Message&m){auto b=encode(m);return !b.empty()&&writen(fd,b.data(),b.size());}
static sockaddr_in address(const std::string&host,int port,bool any=false){sockaddr_in a{};a.sin_family=AF_INET;a.sin_port=htons(static_cast<std::uint16_t>(port));if(host=="0.0.0.0"||any)a.sin_addr.s_addr=htonl(INADDR_ANY);else if(::inet_pton(AF_INET,host.c_str(),&a.sin_addr)!=1)throw std::runtime_error("invalid IPv4 address: "+host);return a;}
static int make_server(const Options&o,int type){Fd s(::socket(AF_INET,type,0));if(s.n<0)throw std::runtime_error(std::string("socket: ")+std::strerror(errno));int yes=1;setsockopt(s.n,SOL_SOCKET,SO_REUSEADDR,&yes,sizeof(yes));auto a=address(o.host,o.port);if(::bind(s.n,reinterpret_cast<sockaddr*>(&a),sizeof(a))<0)throw std::runtime_error(std::string("bind: ")+std::strerror(errno));return s.release();}
int run_server(const Options&o){stopping=false;::signal(SIGINT,on_signal);::signal(SIGTERM,on_signal);try{if(o.protocol=="tcp"){Fd listener(make_server(o,SOCK_STREAM));if(::listen(listener.n,128)<0)throw std::runtime_error(std::string("listen: ")+std::strerror(errno));std::atomic<unsigned long> ids{1};std::mutex workers_m;std::vector<std::thread>workers;std::cout<<"NetPulse TCP server listening on "<<o.host<<":"<<o.port<<" (Ctrl-C to stop)\n";while(!stopping){pollfd p{listener.n,POLLIN,0};int pr=::poll(&p,1,250);if(pr<0){if(errno==EINTR)continue;throw std::runtime_error("poll failed");}if(pr==0)continue;sockaddr_in peer{};socklen_t plen=sizeof(peer);int c=::accept(listener.n,reinterpret_cast<sockaddr*>(&peer),&plen);if(c<0){if(errno==EINTR||errno==EAGAIN)continue; if(stopping)break;std::cerr<<"accept: "<<std::strerror(errno)<<"\n";continue;}auto id=ids++;char ip[INET_ADDRSTRLEN]{};inet_ntop(AF_INET,&peer.sin_addr,ip,sizeof(ip));std::cout<<"[INFO] client="<<id<<" connected from "<<ip<<":"<<ntohs(peer.sin_port)<<"\n";std::lock_guard<std::mutex> lock(workers_m);workers.emplace_back([c,id](){Fd client(c);while(!stopping){Message m;if(!tcp_recv(client.n,m))break;Message r{m.type==MessageType::Ping?MessageType::Pong:MessageType::Echo,m.sequence,m.timestamp_ns,m.payload};if(!tcp_send(client.n,r))break;}std::cout<<"[INFO] client="<<id<<" disconnected\n";});}if(listener.n>=0)::shutdown(listener.n,SHUT_RDWR);for(auto&t:workers)if(t.joinable())t.join();return 0;}else if(o.protocol=="udp"){Fd s(make_server(o,SOCK_DGRAM));std::cout<<"NetPulse UDP server listening on "<<o.host<<":"<<o.port<<" (Ctrl-C to stop)\n";std::vector<std::uint8_t>b(kHeaderSize+kMaxPayload);while(!stopping){pollfd p{s.n,POLLIN,0};int r=::poll(&p,1,250);if(r<0){if(errno==EINTR)continue;throw std::runtime_error("poll failed");}if(!r)continue;sockaddr_in peer{};socklen_t pl=sizeof(peer);ssize_t n=recvfrom(s.n,b.data(),b.size(),0,reinterpret_cast<sockaddr*>(&peer),&pl);if(n<0){if(errno==EINTR)continue;std::cerr<<"recvfrom: "<<std::strerror(errno)<<"\n";continue;}Message m;std::string e;if(!decode(b.data(),static_cast<std::size_t>(n),m,e)){std::cerr<<"[WARN] malformed UDP datagram: "<<e<<"\n";continue;}Message reply{m.type==MessageType::Ping?MessageType::Pong:MessageType::Echo,m.sequence,m.timestamp_ns,m.payload};auto out=encode(reply);if(!out.empty()&&sendto(s.n,out.data(),out.size(),0,reinterpret_cast<sockaddr*>(&peer),pl)<0)std::cerr<<"sendto: "<<std::strerror(errno)<<"\n";}return 0;}else throw std::runtime_error("protocol must be tcp or udp");}catch(const std::exception&e){std::cerr<<"[ERROR] "<<e.what()<<"\n";return 1;}}
static int connect_tcp(const Options&o){Fd s(::socket(AF_INET,SOCK_STREAM,0));if(s.n<0)throw std::runtime_error("socket failed");timeval tv{ o.timeout_ms/1000, (o.timeout_ms%1000)*1000 };setsockopt(s.n,SOL_SOCKET,SO_RCVTIMEO,&tv,sizeof(tv));setsockopt(s.n,SOL_SOCKET,SO_SNDTIMEO,&tv,sizeof(tv));auto a=address(o.host,o.port);if(::connect(s.n,reinterpret_cast<sockaddr*>(&a),sizeof(a))<0)throw std::runtime_error(std::string("connect: ")+std::strerror(errno));return s.release();}
static int make_udp_client(const Options&o,sockaddr_in&dest){Fd s(::socket(AF_INET,SOCK_DGRAM,0));if(s.n<0)throw std::runtime_error("socket failed");dest=address(o.host,o.port);timeval tv{o.timeout_ms/1000,(o.timeout_ms%1000)*1000};setsockopt(s.n,SOL_SOCKET,SO_RCVTIMEO,&tv,sizeof(tv));return s.release();}
int run_client(const Options&o){try{if(o.protocol=="tcp"){Fd s(connect_tcp(o));std::cout<<"Connected to TCP "<<o.host<<":"<<o.port<<". Type text; /quit exits.\n";std::string line;std::uint32_t seq=1;while(std::getline(std::cin,line)&&line!="/quit"){Message m{MessageType::Echo,seq++,now_ns(),line};auto start=std::chrono::steady_clock::now();if(!tcp_send(s.n,m))throw std::runtime_error("send failed");Message r;if(!tcp_recv(s.n,r))throw std::runtime_error("server disconnected or response timed out");double ms=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count();std::cout<<"echo [seq="<<r.sequence<<", RTT="<<ms<<" ms]: "<<r.payload<<"\n";}return 0;}if(o.protocol=="udp"){sockaddr_in dest{};Fd s(make_udp_client(o,dest));std::cout<<"UDP client to "<<o.host<<":"<<o.port<<". Type text; /quit exits.\n";std::string line;std::uint32_t seq=1;std::vector<std::uint8_t>b(kHeaderSize+kMaxPayload);while(std::getline(std::cin,line)&&line!="/quit"){Message m{MessageType::Echo,seq++,now_ns(),line};auto out=encode(m);auto t=std::chrono::steady_clock::now();if(sendto(s.n,out.data(),out.size(),0,reinterpret_cast<sockaddr*>(&dest),sizeof(dest))<0)throw std::runtime_error("sendto failed");ssize_t n=recv(s.n,b.data(),b.size(),0);if(n<0){std::cerr<<"timeout waiting for UDP response\n";continue;}Message r;std::string e;if(!decode(b.data(),static_cast<std::size_t>(n),r,e)){std::cerr<<"invalid response: "<<e<<"\n";continue;}std::cout<<"echo [seq="<<r.sequence<<", RTT="<<std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-t).count()<<" ms]: "<<r.payload<<"\n";}return 0;}throw std::runtime_error("protocol must be tcp or udp");}catch(const std::exception&e){std::cerr<<"[ERROR] "<<e.what()<<"\n";return 1;}}
int run_benchmark(const Options&o){if(o.count<1||o.count>10000000||o.size<0||static_cast<std::size_t>(o.size)>kMaxPayload||o.clients!=1){std::cerr<<"[ERROR] count must be 1..10000000, size 0..60000; current build supports --clients 1 only\n";return 2;}try{Summary s;auto begin=std::chrono::steady_clock::now();std::uint32_t seq=1;std::string payload(static_cast<std::size_t>(o.size),'x');if(o.protocol=="tcp"){Fd fd(connect_tcp(o));for(int i=0;i<o.count;++i){Message m{MessageType::Ping,seq++,now_ns(),payload};auto b=encode(m);auto t=std::chrono::steady_clock::now();++s.sent;s.bytes_sent+=static_cast<double>(b.size());if(!tcp_send(fd.n,m)){++s.errors;break;}Message r;if(!tcp_recv(fd.n,r)){++s.errors;break;}double ms=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-t).count();s.rtt_ms.push_back(ms);++s.received;++s.success;s.bytes_received+=static_cast<double>(b.size());if(o.interval_ms>0)std::this_thread::sleep_for(std::chrono::milliseconds(o.interval_ms));}}else if(o.protocol=="udp"){sockaddr_in dest{};Fd fd(make_udp_client(o,dest));std::vector<std::uint8_t>b(kHeaderSize+kMaxPayload);std::vector<bool> seen(static_cast<std::size_t>(o.count)+1,false);for(int i=0;i<o.count;++i){Message m{MessageType::Ping,seq++,now_ns(),payload};auto out=encode(m);auto t=std::chrono::steady_clock::now();++s.sent;s.bytes_sent+=static_cast<double>(out.size());if(sendto(fd.n,out.data(),out.size(),0,reinterpret_cast<sockaddr*>(&dest),sizeof(dest))<0){++s.errors;continue;}pollfd p{fd.n,POLLIN,0};int ready=poll(&p,1,o.timeout_ms);if(ready>0){ssize_t n=recv(fd.n,b.data(),b.size(),0);if(n>0){Message r;std::string e;if(decode(b.data(),static_cast<std::size_t>(n),r,e)&&r.sequence>0&&r.sequence<=static_cast<std::uint32_t>(o.count)){if(!seen[r.sequence]){seen[r.sequence]=true;++s.received;++s.success;s.bytes_received+=static_cast<double>(n);s.rtt_ms.push_back(std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-t).count());}}else ++s.errors;}else ++s.errors;}else ++s.errors;if(o.interval_ms>0)std::this_thread::sleep_for(std::chrono::milliseconds(o.interval_ms));}}else throw std::runtime_error("protocol must be tcp or udp");s.duration_s=std::chrono::duration<double>(std::chrono::steady_clock::now()-begin).count();Metrics m=calculate(s);std::cout<<"\nNetPulse benchmark ("<<o.protocol<<")\nSent: "<<s.sent<<"  Received: "<<s.received<<"  Successful: "<<s.success<<"  Errors/timeouts: "<<s.errors<<"\n";if(o.protocol=="udp")std::cout<<"Estimated packet loss: "<<(s.sent?100.0*static_cast<double>(s.sent-s.received)/static_cast<double>(s.sent):0)<<"%\n";std::cout<<"Duration: "<<s.duration_s<<" s\nRTT min/avg/median/p95/p99: "<<m.min_ms<<" / "<<m.avg_ms<<" / "<<m.median_ms<<" / "<<m.p95_ms<<" / "<<m.p99_ms<<" ms\nApplication received throughput: "<<m.bytes_per_sec<<" B/s ("<<m.mib_per_sec<<" MiB/s)\nSuccessful exchanges/s: "<<m.messages_per_sec<<"\n";if(!o.output.empty()){std::string e;if(!export_results(s,m,o.output,e))throw std::runtime_error(e);std::cout<<"Exported: "<<o.output<<".csv and "<<o.output<<".json (unless extension supplied)\n";}return 0;}catch(const std::exception&e){std::cerr<<"[ERROR] "<<e.what()<<"\n";return 1;}}
}
